The proof of asymptotic similarity of the AR and conditional tests in Proposition \ref{prop:AR_validity} and Theorem \ref{thm:validity_cond_wald} uses the sub-sequencing techniques from \cite{andrews/cheng/guggenberger:2020}. Specifically, I verify their Assumption B\textsuperscript{*} in the following Proposition \ref{prop:subsequence_AR_validity}. 


\begin{proposition}
\label{prop:subsequence_AR_validity}
For any subsequence $\{p_n\}$ of $\{n\}$ and any sequence $\{(\lambda_{p_n}, F_{p_n}) \in \mathcal{P}_0\}$ for which 
\begin{enumerate}
	\item $\theta_{F_{p_n}} \to \theta_\infty \in \Theta$, where $\theta_{F_{p_n}}$ is a sequence of parameters such that $(\theta_{F_{p_n}}, F_{p_n}) \in \mathcal{P}$ and $\lambda_{{p_n}} = c'\theta_{F_{p_n}}$;
	\item $\beta_{F_{p_n}, d\ell} \to \beta_{\infty,d\ell}$ for $d = 0,1$ and $\ell = 0,1,\ldots,K$;
	\item $\sigma^2_{F_{p_n}, d\ell} \to \sigma^2_{\infty, d\ell}$ for $d = 0,1$ and $\ell = 0,1,\ldots,K$;
	\item $p_{F_{p_n}}(z_\ell) \to p_\infty(z_\ell)$ for all $\ell = 0,1,\ldots,K$;
	\item $q_{F_{p_n}}(z_\ell) \to q_{\infty}(z_\ell)$ for all $\ell = 0,1,\ldots,K$;
\end{enumerate}
The following result holds:
\begin{enumerate}
\item[(a)] the convergence of the type-I error rate of AR test:
\begin{equation*}
    \lim_{n\to\infty} \Prob_{F_{p_n}}\left(\text{AR}_{p_n,k}(\lambda_{p_n}) > q_{\chi_1^2}(1-\alpha)\right) = \alpha, \text{ for } k = 1,\ldots,K,
\end{equation*}
\item[(b)] 
Suppose further that 
\[
    \sqrt{p_n}\|\pi_{F_{p_n}}\| \to \psi_\infty\in [0,\infty], \text{~and~} \pi_{F_{p_n}}/\|\pi_{F_{p_n}}\| \to \iota_\infty,
\] 
where $\iota_\infty$ is a unit vector, then we have the convergence of the type-I error rate of the conditional test
\begin{equation*}
    \lim_{n\to\infty} \Prob_{F_{p_n}}\left(W_{p_n}(\lambda_{p_n}) > q_{W^*}(1-\alpha)\right) = \alpha.
\end{equation*}
\end{enumerate}
\end{proposition}

\bigskip


\begin{proof}[Proof of Proposition \ref{prop:AR_validity}]
This proposition is a consequence from Corollary 2.1(c) of \citet{andrews/cheng/guggenberger:2020} after replacing “CP (Coverage Probability)” with “RP (Null Rejection Probability)” as noted in Comment 4 below their Theorem 2.1.

Assumption B\textsuperscript{*} in their paper is verified by Proposition~\ref{prop:subsequence_AR_validity}(a) by taking their parameter $\lambda$ to be $(\lambda, F)$ in our notation, and by letting their function $h(\lambda)$ correspond to $(\theta, \beta, {\sigma^2_{d\ell}}_{d,\ell}, p, q)$, where $\theta$ is an element of $\Theta$ satisfying $c'\theta = \lambda$ and $(\theta, F) \in \mathcal{P}$. (By the definition of $\mathcal{P}_0$, such a $\theta$ exists.)
\end{proof}

































\bigskip


\begin{proof}[Proof of Theorem \ref{thm:validity_cond_wald}]
This proposition is a consequence from Corollary 2.1(c) of \citet{andrews/cheng/guggenberger:2020} after replacing “CP (Coverage Probability)” with “RP (Null Rejection Probability)” as noted in Comment 4 below their Theorem 2.1.

Assumption B\textsuperscript{*} in their paper is verified by Proposition~\ref{prop:subsequence_AR_validity}(b) 
by taking their parameter $\lambda$ as $(\lambda, F)$ in our notation, 
and their function $h_n(\lambda)$ to correspond to $(\theta, \beta, \{\sigma^2_{d\ell}\}_{d,\ell}, p, q, \sqrt{n}\|\pi\|, \pi/\|\pi\|)$, 
where $\theta$ is an element of $\Theta$ satisfying $c'\theta = \lambda$ and $(\theta, F) \in \mathcal{P}$.
\end{proof}








\bigskip



\begin{proof}[Proof of Proposition \ref{prop:subsequence_AR_validity}]
For simplicity of notations, the proof is shown for the full sequence $\{n\}$. Then, we note that the same proof goes through with $p_n$ in place of $n$.

\medskip
\underline{Part (a)}: 
Note that $g_k(\lambda)$ is a continuously differentiable function of $\lambda$, $p$, $\beta_1$, and $\beta_0$. Applying Delta method and the convergence in Lemma \ref{lem:convergence_p_beta}(a) to the sample moment $\hat{g}_k(\lambda)$ yields
\begin{align*}
    \sqrt{n}\hat{g}_k(\lambda_{n})
    & = [\partial_{p'}{g}_k(\lambda_n)] \hat{Z}_p + [\partial_{\beta_1'}{g}_k(\lambda_n)] \hat{Z}_{\beta_1} + [\partial_{\beta_0'}{g}_k(\lambda_n)] \hat{Z}_{\beta_0} + o_p(1) \\
    & \xrightarrow{d} \normal(0, s_k^2)
\end{align*}
where 
\[
    s_k^2 = [\partial_{p'}{g}_k(\lambda_\infty)]\Sigma_{p,\infty}[\partial_{p}{g}_k(\lambda_\infty)] + [\partial_{\beta_1'}{g}_k(\lambda_\infty)]\Sigma_{\beta_1,\infty}[\partial_{p}{g}_k(\lambda_\infty)] + [\partial_{\beta_0'}{g}_k(\lambda)]\Sigma_{\beta_0,\infty}[\partial_{\beta_0}{g}_k(\lambda_\infty)],
\]
$\lambda_\infty$ is the limit of $\lambda_n = c'\theta_n$ as $n$ goes to infinity, and $g_k(\lambda_\infty)$ equals $g_k(\lambda)$ by sending $\lambda$, $p$, $\beta_1$, and $\beta_0$ to their limiting values.

Again by Lemma \ref{lem:convergence_p_beta}(b), $\Sigma_{p,\infty}$, $\Sigma_{\beta_1,\infty}$, and $\Sigma_{\beta_0,\infty}$ can be consistenly estimated by their sample analogs $\hat{\Sigma}_p$, $\hat{\Sigma}_{\beta_1}$, and $\hat{\Sigma}_{\beta_0}$ along the drifting sequence, respectively. The continuous mapping theorem then implies that 
\[
    \hat{s}_{k}^2(\lambda_{n}) 
    = \partial_{p'}\hat{g}_k(\lambda_{n}) \hat{\Sigma}_p \partial_{p}\hat{g}_k(\lambda_{n}) +  \partial_{\beta_1'}\hat{g}_k(\lambda_{n}) \hat{\Sigma}_{\beta_1} \partial_{\beta_1}\hat{g}_k(\lambda_{n}) +  \partial_{\beta_0'}\hat{g}_k(\lambda_{n}) \hat{\Sigma}_{\beta_0} \partial_{\beta_0}\hat{g}_k(\lambda_{n}) ~~\xrightarrow{p}~~ s_k^2.
\]
Note that Lemma \ref{lem:pd_variance} implies $s_k^2 \in (0,\infty)$. By Slutsky's theorem, we have
\[
    \frac{\sqrt{n}\hat{g}_k(\lambda_{n})}{\hat{s}_k(\lambda_{n})} ~~\xrightarrow{d}~~ \normal(0,1),
\]
which implies the desired result.

\medskip
\underline{Part (b)}: Following similar arguments in part (a), Lemma \ref{lem:convergence_p_beta} implies that
\begin{equation}
\label{eq:limit_baseline}
\begin{aligned}
     \sqrt{n}\hat{g}(\lambda_{n}) ~~ &\xrightarrow{d} ~~ \mathcal{Z}_{\mathfrak{g}} \equiv \partial_p g(\lambda_\infty) \mathcal{Z}_p  + \partial_{\beta_1} g(\lambda_\infty) \mathcal{Z}_{\beta_1} + \partial_{\beta_0} g(\lambda_\infty) \mathcal{Z}_{\beta_0} \sim \normal(0_{K\times 1}, S_\infty) \\
     \partial_{x} \hat{g}(\lambda_{n}) ~~ &\xrightarrow{p}~~ \partial_x g(\lambda_{\infty}) \quad \text{ for } x \in \{p, \beta_1, \beta_0\} \\
     \hat{\Sigma}_x ~~ &\xrightarrow{p}~~ \Sigma_{x,\infty} \quad \text{ for } x \in \{p, \beta_1, \beta_0\} \\
     \hat{S}(\lambda_n) ~~&\xrightarrow{p}~~ S_\infty
\end{aligned}
\end{equation}
where
\[
    S_\infty  \equiv \partial_p g(\lambda_\infty) \Sigma_{p,\infty} \partial_{p'} g(\lambda_\infty) + \partial_{\beta_1} g(\lambda_\infty) \Sigma_{\beta_1,\infty} \partial_{\beta_1'} g(\lambda_\infty) + \partial_{\beta_0} g(\lambda_\infty) \Sigma_{\beta_0,\infty} \partial_{\beta_0'} g(\lambda_\infty).
\]
and $S_\infty$ is bounded and positive definite by Lemma \ref{lem:pd_variance}. 

\medskip
\textbf{Case 1:} $\psi_\infty < \infty$.
\medskip

In this case, we have
\begin{equation}
\label{eq:limit_2}
\begin{aligned}
\sqrt{n} \hat{\pi} 
    &= \sqrt{n}\pi_{F_n} + [\partial_p \pi] \hat{Z}_p \\
    &\xrightarrow{d} \psi_\infty \iota_\infty + [\partial_p \pi] \mathcal{Z}_p\\
    &\equiv \mathcal{Z}_\pi
\end{aligned}
\end{equation}
and 
\begin{align*}
    \hat{h}(\lambda_n) 
    &= \sqrt{n}\hat{\pi} - [\partial_p \pi] \hat{\Sigma}_p [\partial_{p'}\hat{g}(\lambda_n)] \hat{S}(\lambda_n)^{-1} \sqrt{n}\hat{g}(\lambda_n) \\
    &\xrightarrow{d} \psi_\infty\iota_\infty + [\partial_p \pi] \mathcal{Z}_p - [\partial_p \pi]\Sigma_{p,\infty} [\partial_{p'}g(\lambda_\infty)]S_\infty^{-1} \mathcal{Z}_{\mathfrak{g}}\\
    &\equiv \mathcal{Z}_h
\end{align*}
From the independence $(\mathcal{Z}_{\beta_1}, \mathcal{Z}_{\beta_0}) \indep \mathcal{Z}_p$, it follows that $\mathcal{Z}_h \indep \mathcal{Z}_{\mathfrak{g}}$ since they are jointly normal and uncorrelated.

By continuous mapping theorem, we obtain the asymptotic distribution of the Wald statistic under the null:
\begin{align*}
    W_n(\lambda_n) 
    &= \frac{n\hat{g}(\lambda_n)'\hat{S}(\lambda_n)^{-1} \hat{\pi}\hat{\pi}'\hat{S}(\lambda_n)^{-1}\hat{g}(\lambda_n)}{\hat{\pi}'\hat{S}(\lambda_n)^{-1}\hat{\pi}} \\
    &\xrightarrow{d} \frac{\mathcal{Z}_{\mathfrak{g}}' S_\infty^{-1} \mathcal{Z}_\pi \mathcal{Z}_\pi' S_\infty^{-1} \mathcal{Z}_{\mathfrak{g}}}{\mathcal{Z}_\pi S_\infty^{-1} \mathcal{Z}_\pi}.
\end{align*}
On the other hand, we note that the simulated statistic $W_n^*(\lambda_n)$ can be written as a function of standard normal draw $\eta^*$ and a conditioning statistic 
\begin{equation}
\label{eq:Upsilon_hat}
    \hat{\Upsilon} \equiv (\hat{h}(\lambda_n), ~\hat{S}(\lambda_n), ~\hat{\Sigma}_p, ~\partial_p\hat{g}(\lambda_n)).
\end{equation}
Specifically, we write
\begin{equation}
\label{eq:defn_W_eta_C}
    W_n^*(\lambda_n) = W(\eta^*, \hat{\Upsilon}) \equiv \frac{(\eta^*)'\hat{S}(\lambda_n)^{-1/2} \pi_s(\eta^*,\hat{\Upsilon})\pi_s(\eta^*,\hat{\Upsilon})'\hat{S}(\lambda_n)^{-1/2}\eta^*}{\pi_s(\eta^*,\hat{\Upsilon})'\hat{S}(\lambda_n)^{-1}\pi_s(\eta^*,\hat{\Upsilon})} 
\end{equation}
where 
\[
    \pi_s(\eta^*, \hat{\Upsilon}) \equiv \hat{h}(\lambda_n) + [\partial_p \pi] \hat{\Sigma}_p [\partial_{p'}\hat{g}(\lambda_n)] \hat{S}(\lambda_n)^{-1/2} \eta^*.
\]
Therefore, $\hat{\Upsilon}$ is the source of sampling uncertainty on the simulated statistic $W_n^*(\lambda_n)$.

Let $G(\cdot\mid \hat{\Upsilon})$ denote the CDF of the simulated Wald statistic $W_n^*(\lambda_n)$ conditional on data, i.e.,
\begin{align*}
    G(x\mid \hat{\Upsilon}) 
    &\equiv \Prob(W_n^*(\lambda_n) \leq x \mid \{Y_i, D_i, Z_i\}_{i=1}^n) \\
    &= \Prob(W(\eta^*, \hat{\Upsilon}) \leq x\mid \hat{\Upsilon}).
\end{align*}
Define $q(1-\alpha,\Upsilon)$ as the $(1-\alpha)$-quantile of $G(\cdot \mid \Upsilon)$ for a quartet of elements $\Upsilon$ such as $\hat{\Upsilon}$ in \eqref{eq:Upsilon_hat}. By this definition, the critical value can be expressed as 
\[
    \hat{q}_{W^*}(1-\alpha) = q(1-\alpha,\hat{\Upsilon}).
\]
Next we show that $q(1-\alpha,\Upsilon)$
is a continuous function of $\Upsilon$ on the set $\mathcal{U}$, where
\begin{equation}
    \label{eq:defn_set_C}
    \begin{aligned}
    \mathcal{U} = 
    \{(u_1, u_2, u_3, u_4):~ 
    & u_1 + [\partial_p \pi]u_3u_4'u_2^{-1/2}\eta^* \neq 0_{K\times 1} \text{ a.s.},  \\
    & u_1\in\R^K, u_2 \in \mathbb{S}^{K}_{++}, u_3 \in \mathbb{S}^{K+1}_{++}, u_4 \in \R^{K\times (K+1)}\}.
    \end{aligned}
\end{equation}
Let $\{\Upsilon_n\}$ be a sequence in $\mathcal{U}$ such that $\Upsilon_n \to \Upsilon \in \mathcal{U}$ as $n\to \infty$. Given zero probability of discontinuity in the limit by the definition of $\mathcal{U}$, $\{W(\eta^*,\Upsilon_n)\}_{n \geq 1}$ converges almost surely to $W(\eta^*,\Upsilon)$. This implies the convergence in distribution for any continuity point $x$ of $G(\cdot\mid \Upsilon)$:
\[
    G(x\mid \Upsilon_n) = \Prob_{\eta^*}(W(\eta^*,\Upsilon_n) \leq x) ~~\to~~ \Prob_{\eta^*}(W(\eta^*,\Upsilon) \leq x) = G(x \mid \Upsilon).
\]
The distribution function $G(\cdot\mid \Upsilon)$ is increasing at its $(1-\alpha)$-quantile $q(1-\alpha,\Upsilon)$ because the random variable $W(\eta^*, \Upsilon)$ is continuously distributed. By \citet[Lemma 5]{andrews/guggenberger:2010}, it follows that $q(1-\alpha,\Upsilon_n) \to q(1-\alpha,\Upsilon)$. This establishes continuity of quantile function on the set $\mathcal{U}$.

The convergence results in \eqref{eq:limit_baseline} and \eqref{eq:limit_2} give  
\[
    \hat{\Upsilon} ~~\xrightarrow{d}~~ \Upsilon_\infty \equiv (\mathcal{Z}_h, ~S_\infty, ~\Sigma_{p,\infty}, ~\partial_p g(\lambda_\infty)),
\]
and by Lemma \ref{lem:NS_cond}, we have $\Prob(\Upsilon_\infty \in \mathcal{U}) = 1$. From the continuity of $q(1-\alpha,\Upsilon)$, it follows by continuous mapping theorem that
\[
    W_n(\lambda_n) - q(1-\alpha, \hat{\Upsilon}) ~~\xrightarrow{d}~~ \frac{\mathcal{Z}_{\mathfrak{g}}' S_\infty^{-1} \mathcal{Z}_\pi \mathcal{Z}_\pi' S_\infty^{-1} \mathcal{Z}_{\mathfrak{g}}}{\mathcal{Z}_\pi S_\infty^{-1} \mathcal{Z}_\pi} - q(1-\alpha, \Upsilon_\infty),
\]
which implies
\[
    \Prob_{F_n}\left(W_n(\lambda_n) > q(1-\alpha, \hat{\Upsilon})\right) ~~\to~~ \Prob\left(\frac{\mathcal{Z}_{\mathfrak{g}}' S_\infty^{-1} \mathcal{Z}_\pi \mathcal{Z}_\pi' S_\infty^{-1} \mathcal{Z}_{\mathfrak{g}}}{\mathcal{Z}_\pi S_\infty^{-1} \mathcal{Z}_\pi} > q(1-\alpha, \Upsilon_\infty)\right).
\]
Next, we show that the limit probability on the right-hand side equals $\alpha$. We first examine the conditional probability as follows.
\begin{align*}
    &\Prob\left(\frac{\mathcal{Z}_{\mathfrak{g}}' S_\infty^{-1} \mathcal{Z}_\pi \mathcal{Z}_\pi' S_\infty^{-1} \mathcal{Z}_{\mathfrak{g}}}{\mathcal{Z}_\pi S_\infty^{-1} \mathcal{Z}_\pi} > q(1-\alpha, \Upsilon_\infty) \mid \Upsilon_\infty\right) \\
    &= \Prob\left(\frac{(\eta^*)' S_\infty^{-1/2} \pi_s(\eta^*,\Upsilon_\infty) \pi_s(\eta^*,\Upsilon_\infty)' S_\infty^{-1/2} \eta^*}{\pi_s(\eta^*,\Upsilon_\infty) S_\infty^{-1} \pi_s(\eta^*,\Upsilon_\infty)} > q(1-\alpha, \Upsilon_\infty) \mid \Upsilon_\infty\right) \\
    &= \Prob\left(W(\eta^*,\Upsilon_\infty) > q(1-\alpha, \Upsilon_\infty) \mid \Upsilon_\infty\right) \\
    &= \alpha\quad \text{a.s.}
\end{align*}
The second line holds by the observation that $\eta^*$ and $S_\infty^{-1/2}\mathcal{Z}_{\mathfrak{g}}$ are both independent of $\Upsilon_\infty$, and that $\mathcal{Z}_\pi = \pi_s(S_\infty^{-1/2}\mathcal{Z}_{\mathfrak{g}},~\Upsilon_\infty)$, which has the same distribution as $\pi_s(\eta^*, \Upsilon_\infty)$. The third line holds by the definition of $W(\eta^*,\Upsilon_\infty)$. The last line holds by the definition of $q(1-\alpha,\Upsilon)$, and the fact that $W(\eta^*,\Upsilon)$ is continuously distributed for any $\Upsilon \in \mathcal{U}$. By taking the law of total probability, it follows that the unconditional rejection probability equals $\alpha$ as well. This completes the proof for the case $\psi_\infty < \infty$.

\medskip
\textbf{Case 2:} $\psi_\infty = \infty$.
\medskip

In this case, by the assumption $\sqrt{n}\|\pi_{F_n}\| \to \infty$, we have
\begin{equation}
\label{eq:limit_3}
\begin{aligned}
    \frac{\hat{\pi}}{\|\pi_{F_n}\|} 
    &= \frac{\pi_{F_n}}{\|\pi_{F_n}\|} + O_p(n^{-1/2}\|\pi_{F_n}\|^{-1}) \\
    &= \iota_\infty + o_p(1).
\end{aligned}
\end{equation}
and 
\begin{equation}
\label{eq:h_sqrt_limit}
\begin{aligned}
    \frac{\hat{h}(\lambda_n)}{\sqrt{n}\|\pi_{F_n}\|} 
    &= \frac{\hat{\pi}}{\|\pi_{F_n}\|} - [\partial_p \pi]\hat{\Sigma}_{p}[\partial_{p'} \hat{g}(\lambda_n)]\hat{S}^{-1}\sqrt{n}\hat{g}(\lambda_n) \|\sqrt{n}\pi_{F_n}\|^{-1} \\
    &= \iota_\infty + o_p(1).
\end{aligned}
\end{equation}

From the condition $\iota_\infty \neq 0_{K\times 1}$, \eqref{eq:limit_baseline}, and \eqref{eq:limit_3}, it follows that 
\begin{equation}
\label{eq:test_stat_converge}
    W_n(\lambda_n) = \frac{n\hat{g}(\lambda_n)'\hat{S}(\lambda_n)^{-1} (\hat{\pi}/\|\pi_{F_n}\|)(\hat{\pi}'/\|\pi_{F_n}\|)\hat{S}(\lambda_n)^{-1}\hat{g}(\lambda_n)}{(\hat{\pi}'/\|\pi_{F_n}\|)\hat{S}(\lambda_n)^{-1}(\hat{\pi}/\|\pi_{F_n}\|)} ~~\xrightarrow{d}~~ \chi_1^2.    
\end{equation}
Now we examine the stochastic behavior of critical value $\hat{q}_{W^*}(1-\alpha)$, defined as $(1-\alpha)$-quantile of $W_n^*(\lambda_n)$ conditional on data. First, define a normalized conditioning statistic in the construction of $W_n^*(\lambda_n)$:
\[
    \bar{\Upsilon} \equiv \left(\frac{\hat{h}(\lambda_n)}{\sqrt{n}\|\pi_{F_n}\|}, ~\hat{S}(\lambda_n), ~\hat{\Sigma}_p,  ~\frac{\partial_p\hat{g}(\lambda_n)}{\sqrt{n}\|\pi_{F_n}\|}\right).
\]
By the definition of $q(1-\alpha,\Upsilon)$ introduced in Case 1 and the fact that
\[
    W_n^*(\lambda_n) \equiv W_n(\eta^*, \hat{\Upsilon}) = W_n(\eta^*, \bar{\Upsilon}),
\]
we have 
\[
    \hat{q}_{W^*}(1-\alpha) = q(1-\alpha, \bar{\Upsilon}).
\]
It therefore suffices to obtain the limit of $\bar{\Upsilon}$ as the sample size diverges. By \eqref{eq:limit_baseline}, \eqref{eq:h_sqrt_limit}, and the condition that $\sqrt{n}\|\pi_{F_n}\| \to \infty$, we obtain
\[
    \bar{\Upsilon}~~\xrightarrow{p}~~\bar{\Upsilon}_{\infty} \equiv (\iota_\infty, S_\infty, \Sigma_{p,\infty}, 0_{K \times (K+1)}) ~\in~ \mathcal{U},
\]
where the inclusion in $\mathcal{U}$ follows from $\iota_\infty \neq 0_{K\times 1}$. 
This and the continuity of the quantile function $q(1-\alpha,\cdot)$ give $q(1-\alpha, \bar{\Upsilon}) \xrightarrow{p} q(1-\alpha, \bar{\Upsilon}_{\infty})$. This shows that the $(1-\alpha)$-conditional quantile of $W_n^*(\lambda_n)$ converges in probability to $q(1-\alpha, \bar{\Upsilon}_{\infty})$, which equals the $(1-\alpha)$-quantile of $\chi_1^2$ distribution by replacing $\hat{\Upsilon}$ with $\bar{\Upsilon}_\infty$ in \eqref{eq:defn_W_eta_C}. So we conclude that 
\begin{equation}
\label{eq:critical_value_converge}
        \hat{q}_{W^*}(1-\alpha) ~~\xrightarrow{p}~~ q_{\chi_1^2}(1-\alpha). 
\end{equation}
By \eqref{eq:test_stat_converge} and \eqref{eq:critical_value_converge}, we have $W_n(\lambda_n) - \hat{q}_{W^*}(1-\alpha) \xrightarrow{d} \chi_1^2 - q_{\chi_1^2}(1-\alpha)$. Then the desired conclusion follows by the definition of convergence in distribution.
\end{proof}

The proof of uniform size control in Theorem \ref{thm:uniform_validity} uses the sub-sequencing techniques from \cite{andrews/cheng/guggenberger:2020}. Specifically, we verify part of their Assumption B in the following Proposition \ref{prop:subsequence_MLC_validity}. 




\begin{proposition}
\label{prop:subsequence_MLC_validity}
For any subsequence $\{p_n\}$ of $\{n\}$ and any sequence $\{(\lambda_{p_n}, F_{p_n}) \in \mathcal{P}_0\}$ for which 
\begin{enumerate}
	\item $\theta_{F_{p_n}} \to \theta_\infty \in \Theta$, where $\theta_{F_{p_n}}$ is a sequence of parameters such that $(\theta_{F_{p_n}}, F_{p_n}) \in \mathcal{P}$ and $\lambda_{{p_n}} = c'\theta_{F_{p_n}}$;
	\item $\beta_{F_{p_n}, d\ell} \to \beta_{\infty,d\ell}$ for $d = 0,1$ and $\ell = 0,1,\ldots,K$;
	\item $\sigma^2_{F_{p_n}, d\ell} \to \sigma^2_{\infty, d\ell}$ for $d = 0,1$ and $\ell = 0,1,\ldots,K$;
	\item $p_{F_{p_n}}(z_\ell) \to p_\infty(z_\ell)$ for all $\ell = 0,1,\ldots,K$;
	\item $q_{F_{p_n}}(z_\ell) \to q_{\infty}(z_\ell)$ for all $\ell = 0,1,\ldots,K$;



	\item $B_{F_{p_n}} \to B_{\infty}$ and $C_{F_{p_n}} \to C_{\infty}$;
	\item $\sqrt{p_n}\tau_{j,F_{p_n}} \to t_j \in [0,\infty]$ for all $j = 1, \ldots, 2(M+1)$;
	\item $\iota_{n} \equiv \frac{\Psi_{F_{p_n}} B_{F_{p_n}}'c}{\|\Psi_{F_{p_n}} B_{F_{p_n}}'c\|}\to \iota_\infty \in \R^{2(M+1)}$, where $\Psi_{F_{p_n}} \in \R^{2(M+1)\times 2(M+1)}$ is a normalizing matrix defined in equation \eqref{eq:defn_S},\footnote{Note that the denominator $\|\Psi_{F_n}B_{F_n}'c\| \neq 0$ since $\Psi_{F_n}$ and $B_{F_n}$ are both full-rank matrices and the weight $c$ is nonzero. Hence $\iota_n$ is properly defined for each $n \geq 1$ and satisfies $\|\iota_n\| = 1$.}
\end{enumerate}
we have 
\[
	\limsup_{n\to\infty} \Prob_{F_{p_n}}\left(\inf_{c'\theta = \lambda_{p_n}} \text{MLC}_{p_n}(\theta) > q_{(1+a)\chi_1^2 + a\chi_{2K+1}^2}(1-\alpha)\right) \leq \alpha.
\]
\end{proposition}



\bigskip


\begin{proof}[Proof of Theorem \ref{thm:uniform_validity}]
This proposition is a consequence from Corollary 2.1(a) of \citet{andrews/cheng/guggenberger:2020} after replacing “CP (Coverage Probability)” with “RP (Null Rejection Probability)” as noted in Comment 4 below their Theorem 2.1.

Assumption B in their paper is verified by Proposition~\ref{prop:subsequence_MLC_validity}
by taking their parameter $\lambda$ as $(\lambda, F)$ in our notation, 
and their function $h_n(\lambda)$ to correspond to $(\theta, \beta, \{\sigma^2_{d\ell}\}_{d,\ell}, p, q,B,C,\{\sqrt{n}\tau_j\}_{j=1}^{2(M+1)}, \iota_n)$, 
where $\theta$ is an element of $\Theta$ satisfying $c'\theta = \lambda$ and $(\theta, F) \in \mathcal{P}$.
\end{proof}





























\bigskip



\begin{proof}[Proof of Proposition \ref{prop:subsequence_MLC_validity}]
For simplicity of notations, the proof is shown for the full sequence $\{n\}$. Then, we note that the same proof goes through with $p_n$ in place of $n$.


By Lemma \ref{lem:convergence_p_beta}(a), we have 
\[
	\sqrt{n}
	\begin{pmatrix}
		\hat{p} - p_{F_n} \\
		\hat{\beta} - \beta_{F_n}
	\end{pmatrix}
	~~=~~
	\begin{bmatrix}
		\hat{Z}_p \\
		\hat{Z}_\beta
	\end{bmatrix}
	~~\xrightarrow{d}~~
	\normal\left(0_{3(K+1)\times 1},  \quad 
	\begin{bmatrix}
		\Sigma_{p,\infty} & 0_{(K+1)\times 2(K+1)} \\
		0_{2(K+1)\times (K+1)} & \Sigma_{\beta,\infty}
	\end{bmatrix}\right)
\]
This implies
	\begin{equation}
	\label{eq:A_mat_asymptotics}
		\sqrt{n}(\hat{A} - A_{F_n}) 
		= \begin{bmatrix}
			\begin{pmatrix}
				L_0(p_{F_n})\hat{Z}_p, & \ldots & L_M(p_{F_n})\hat{Z}_p  
			\end{pmatrix}
			& 0_{(K+1)\times(M+1)} \\
			0_{(K+1)\times (M+1)} & 
			\begin{pmatrix}
				R_0(p_{F_n})\hat{Z}_p, & \ldots & R_M(p_{F_n})\hat{Z}_p  
			\end{pmatrix}
		\end{bmatrix}
		+o_p(1)
	\end{equation}
	where
	\begin{align*}
		& L_m(p) = \diag\{\lambda_{1m}'(p(z_0)), \ldots,\lambda_{1m}'(p(z_K))\} \\
		& R_m(p) = \diag\{\lambda_{0m}'(p(z_0)), \ldots, \lambda_{0m}'(p(z_K))\}.
	\end{align*}

By continuous mapping theorem, we have 
\begin{align*}
	\sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta})
	&= \sqrt{n}(\hat{A} - A_{F_n})\theta_{F_n} - \sqrt{n}(\hat{\beta} - \beta_{F_n}) \\
	&= \begin{bmatrix}
		\begin{pmatrix}
			L_0({p}_{F_n})\hat{Z}_p, & \ldots & L_M({p}_{F_n})\hat{Z}_p  
		\end{pmatrix}
		& 0_{(K+1)\times(M+1)} \\
		0_{(K+1)\times (M+1)} & 
		\begin{pmatrix}
			R_0({p}_{F_n})\hat{Z}_p, & \ldots & R_M({p}_{F_n})\hat{Z}_p  
		\end{pmatrix}
	\end{bmatrix}
	\begin{bmatrix}
	\theta_{1,F_n} \\
	\theta_{0,F_n}
	\end{bmatrix} \\
	  & \quad - \hat{Z}_\beta + o_p(1) \\
	&\xrightarrow{d}
	\begin{bmatrix}
		\diag\left\{\sum_{m=0}^M \theta_{1m,\infty} \lambda_{1m}'({p}_{\infty}(z_\ell)): \ell = 0,1,\ldots, K\right\} \\
		\diag\left\{\sum_{m=0}^M \theta_{0m,\infty} \lambda_{0m}'({p}_{\infty}(z_\ell)): \ell = 0,1,\ldots, K\right\}
	\end{bmatrix} 
	\mathcal{Z}_p - \mathcal{Z}_\beta\\
	&= H(p_\infty,\theta_\infty)\mathcal{Z}_p - \mathcal{Z}_\beta.
\end{align*}
where we define
	\[
		H(p,\theta) 
		\equiv
		\begin{bmatrix}
			\diag\left\{\sum_{m=0}^M \theta_{1m} \lambda_{1m}'({p}(z_{\ell})): \ell = 0,1,\ldots, K\right\} \\
			\diag\left\{\sum_{m=0}^M \theta_{0m} \lambda_{0m}'({p}(z_{\ell})): \ell = 0,1,\ldots, K\right\}
		\end{bmatrix}.
	\]
Let 
\[
	\mathcal{Z}_{\mathfrak{m}} \equiv H(p_\infty,\theta_\infty)\mathcal{Z}_p - \mathcal{Z}_\beta.
\] 
Following Lemma \ref{lem:convergence_p_beta}, the condition $\theta_{F_n} \to \theta_{\infty}$, and note that $\{\lambda_{dm}'(\cdot)\}$ are continuouly differentiable by the continuity of $h_m(\cdot)$, continuous mapping theorem implies
\begin{align}
	\hat{\Omega}(\theta_{F_n}) 
	&~~=~~ H(\hat{p}, \theta_{F_n}) \hat{\Sigma}_p H(\hat{p}, \theta_{F_n})' + \hat{\Sigma}_\beta \notag \\
	&~~\xrightarrow{p}~~
	H(p_{\infty}, \theta_{\infty}) {\Sigma}_{p,\infty} H(p_{\infty}, \theta_{\infty})' + {\Sigma}_{\beta,\infty} \notag \\
	&~~=~~ \var(\mathcal{Z}_{\mathfrak{m}}) \label{eq:convergence_Omega} 
	\end{align}
and
\begin{align}
	\hat{\Gamma}_j(\theta_{F_n})
	&~~=~~ M_j(\hat{p})\hat{\Sigma}_p H(\hat{p}, \theta_{F_n})' \notag \\
	&~~\xrightarrow{p}~~
	M_j(p_{\infty}){\Sigma}_{p,\infty} H(p_{\infty}, \theta_{\infty})' \notag \\
	&~~=~~ \cov(M_j(p_\infty)\mathcal{Z}_p, \mathcal{Z}_{\mathfrak{m}}). \label{eq:convergence_Gamma}
\end{align}
where $M_j(p)$ is defined in \eqref{eq:defn_M_mat}. 
Note that $\var(\mathcal{Z}_{\mathfrak{m}})$ is positive definite by the positive definiteness of $\Sigma_{\beta,\infty}$, which is in turn implied by the parameter space restriction on $\mathcal{P}$. For each $j = 1,\ldots,2(M+1)$, then we have
\begin{align*}
	\sqrt{n}(\hat{d}_j(\theta_{F_n}) - a_{j,F_n}) 
	&= \sqrt{n}(\hat{a}_j - a_{j,F_n}) - \hat{\Gamma}_j(\theta_{F_n})\hat{\Omega}(\theta_{F_n})^{-1}\sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta}) \\
	&\xrightarrow{d} \underbrace{M_j(p_{\infty}) \mathcal{Z}_p - \cov(M_j(p_\infty)\mathcal{Z}_p, \mathcal{Z}_{\mathfrak{m}})\var(\mathcal{Z}_{\mathfrak{m}})^{-1}\mathcal{Z}_{\mathfrak{m}}}_{\equiv \mathcal{Z}_{d_j}},
\end{align*}
where the second line holds by combining results from \eqref{eq:A_mat_asymptotics}, \eqref{eq:convergence_Omega}, and \eqref{eq:convergence_Gamma}. Then we observe that
\[
	\cov(\mathcal{Z}_{d_j}, \mathcal{Z}_{\mathfrak{m}})
	= 0_{2(K+1)\times 2(K+1)}.
\]
This shows
\begin{equation}
\label{eq:convergence_moment}
	\sqrt{n}
	\begin{pmatrix}
		\hat{A}\theta_{F_n} - \hat{\beta} \\
		\operatorname*{vec}(\hat{D}(\theta_{F_n})) - \operatorname*{vec}(A_{F_n})
	\end{pmatrix}
	~~\xrightarrow{d}~~
	\begin{pmatrix}
		\mathcal{Z}_{\mathfrak{m}} \\
		\operatorname*{vec}(\mathcal{Z}_D)
  \end{pmatrix},
\end{equation}
where $\mathcal{Z}_D = (\mathcal{Z}_{d_1}, \ldots, \mathcal{Z}_{d_{2(M+1)}})$ is independent of $\mathcal{Z}_{\mathfrak{m}}$. 



Based on \eqref{eq:convergence_moment}, applying Lemma \ref{lem:new_cond_stat} yields
\[
	n^{1/2}\widetilde{D}(\theta_{F_n}) B_{F_n} \Psi_{F_n} 
	~~\xrightarrow{d}~~
	\mathcal{D}_\xi
\]
where $\mathcal{D}_\xi$ is of full column rank with probability one and is also independent of $\mathcal{Z}_{\mathfrak{m}}$, and $\Psi_{F_n}$ is a diagonal matrix with positive diagonal elements 
\begin{equation}
\label{eq:defn_S}
		\Psi_{F_n} = 
		\begin{bmatrix}
		\begin{pmatrix}
		(\sqrt{n}\tau_{1,F_n})^{-1} & & \\
		& \ddots & \\
		& & (\sqrt{n}\tau_{q,F_n})^{-1} 
		\end{pmatrix} & 0_{q\times (2(M+1) - q)} \\
		0_{(2(M+1) - q)\times q} & I_{2(M+1) - q}
		\end{bmatrix}
\end{equation}
with $q \equiv \max\{j: t_j = \infty\}$.


	Define a normalizing constant $\gamma_n \equiv \|\sqrt{n} \Psi_{F_n} B_{F_n}'c\|^{-1}$. 






	 By continuous mapping theorem and given that $\mathcal{D}_\xi$ is of full rank with probability one, we have
	\begin{align}
		\hat{Q}(\theta_{F_n}) \gamma_n
		&~~=~~ 
		\hat{\Omega}(\theta_{F_n})^{-1/2}\left(\sqrt{n}\widetilde{D}(\theta_{F_n})B_{F_n} \Psi_{F_n} \right) \notag \\
		&~~\quad \left[\left(\sqrt{n}\widetilde{D}(\theta_{F_n})B_{F_n} \Psi_{F_n}\right)'\hat{\Omega}(\theta_{F_n})^{-1} \left(\sqrt{n}\widetilde{D}(\theta_{F_n})B_{F_n} \Psi_{F_n}\right)\right]^{-1}\underbrace{\frac{\sqrt{n} \Psi_{F_n} B_{F_n}' c}{\|\sqrt{n} \Psi_{F_n} B_{F_n}'c\|}}_{\iota_n} \notag \\
		&~~\xrightarrow{d}~~
		\mathcal{Q} ~~\equiv~~
			 \var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{D}_\xi [\mathcal{D}_\xi'\var(\mathcal{Z}_{\mathfrak{m}})^{-1}\mathcal{D}_\xi ]^{-1} \iota_\infty.
		\label{eq:convergence_Q}
	\end{align}
Since $\iota_\infty \neq 0_{2(M+1)\times 1}$ and $\mathcal{D}_\xi$ has full rank with probability one, we conclude that $\mathcal{Q}$ is nonzero almost surely and  independent of $\mathcal{Z}_{\mathfrak{m}}$ by the independence between $\mathcal{D}_\xi$ and $\mathcal{Z}_{\mathfrak{m}}$.

	Then it follows that 
	\begin{align*}
	\text{MRLM}_n(\theta_{F_n}) 
	&~~=~~ \sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta})'\hat{\Omega}(\theta_{F_n})^{-1/2} P_{\hat{Q}(\theta_{F_n})}\hat{\Omega}(\theta_{F_n})^{-1/2}\sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta}) \\
	&~~=~~ \sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta})'\hat{\Omega}(\theta_{F_n})^{-1/2} P_{\hat{Q}(\theta_{F_n})\gamma_n}\hat{\Omega}(\theta_{F_n})^{-1/2}\sqrt{n}(\hat{A}\theta_{F_n} - \hat{\beta}) \\
	&~~\xrightarrow{d}~~ \mathcal{Z}_{\mathfrak{m}}'\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2} \mathcal{Z}_{\mathfrak{m}} \\
	&~~\sim~~ \chi_1^2
	\end{align*}
	The third line holds by continuous mapping theorem based on \eqref{eq:convergence_Omega},  \eqref{eq:convergence_moment}, and \eqref{eq:convergence_Q}. The last line follows by that $\mathcal{Q}$ is nonzero almost surely and $\mathcal{Q} \indep \mathcal{Z}_{\mathfrak{m}}$, thus 
	\[
		\mathcal{Z}_{\mathfrak{m}}'\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2} \mathcal{Z}_{\mathfrak{m}} ~~\sim~~ \chi_1^2
		\quad 
		\text{conditional on $\mathcal{Q}$}
	\]
	implies the unconditional distribution
	\[
		\mathcal{Z}_{\mathfrak{m}}'\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2} \mathcal{Z}_{\mathfrak{m}} ~~\sim~~ \chi_1^2.
	\]

	We apply similar arguments to the difference between AR and MRLM statistics, yielding
	\[
	\begin{bmatrix}
	\text{AR}_n(\theta_{F_n}) - \text{MRLM}_n(\theta_{F_n}) \\
	\text{MRLM}_n(\theta_{F_n})
	\end{bmatrix}
 ~~\xrightarrow{d}~~ 
	\begin{bmatrix}
	\mathcal{Z}_{\mathfrak{m}}'\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}M_{\mathcal{Q}} \var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}}  \\
	\mathcal{Z}_{\mathfrak{m}}'\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}P_{\mathcal{Q}} \var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}} 
	\end{bmatrix}
	~~\sim~~
	\begin{bmatrix}
	\chi_{2K + 1}^2 \\
	\chi_{1}^2
	\end{bmatrix},
	\]
	where $M_\mathcal{Q} \equiv I - P_\mathcal{Q}$ denotes the annihilator operator. Note that $\chi_{2K + 1}^2$ is independent of $\chi_1^2$ because $(P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}}, \quad M_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}})$ are uncorrelated:
	\begin{align*}
	\cov(P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}}, M_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}})
	&= \Exp\left(\cov(P_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}}, M_{\mathcal{Q}}\var(\mathcal{Z}_{\mathfrak{m}})^{-1/2}\mathcal{Z}_{\mathfrak{m}} \mid \mathcal{Q})\right) \\
	&= \Exp(P_{\mathcal{Q}}M_{\mathcal{Q}}) \\
	&= 0_{2(K+1)\times 2(K+1)}.
	\end{align*}
	The first line holds by the law of total covariance and the fact that $\Exp[\mathcal{Z}_{\mathfrak{m}}\mid \mathcal{Q}] = \Exp[\mathcal{Z}_{\mathfrak{m}}] = 0$. The second line holds by the independence between $\mathcal{Q}$ and $\mathcal{Z}_{\mathfrak{m}}$. The third line holds by the definition $M_{\mathcal{Q}} = I - P_{\mathcal{Q}}$. So we have
	\[
		\text{MLC}_n(\theta_{F_n}) = \text{MRLM}_n(\theta_{F_n}) + a\cdot\text{AR}_n(\theta_{F_n}) ~~\xrightarrow{d}~~ (1+a)\chi_1^2 + a\chi_{2K+1}^2 
	\]
	by continuous mapping theorem.

	As a result, we show that
	\begin{align*}
		& \limsup_{n\to\infty} \Prob_{F_{n}}\left(\inf_{c'\theta = \lambda_{n}} \text{MLC}_n(\theta) > q_{(1+a)\chi_1^2 + a\chi_{2K+1}^2 }(1-\alpha)\right) \\
		& \leq 
		\lim_{n\to\infty} \Prob_{F_{n}}\left( \text{MLC}_n(\theta_{F_n}) > q_{(1+a)\chi_1^2 + a\chi_{2K+1}^2 }(1-\alpha)\right) \\
		& = \alpha.
	\end{align*}
	Then the proof is complete.
\end{proof}



