\begin{proof}[Proof of Lemma \ref{lem:bias_formula_general}]
Applying FWL theorem to partial out the linear effects of $W$ in the misspecified regression \eqref{eq:shortreg}, we have
\begin{align*}
    &Y^{\perp W\mid D=1} = \tilde{\rho}_1 \lambda_1(P)^{\perp W\mid D=1} + Y^{\perp W, \lambda_1(P)\mid D=1}  &\text{conditional on } D = 1\\
    &Y^{\perp W\mid D=0} = \tilde{\rho}_0 \lambda_0(P)^{\perp W\mid D=0} + Y^{\perp W, \lambda_0(P)\mid D=0} &\text{conditional on } D = 0
\end{align*}
Conditional on $D=d$, simple OLS regression gives 
\begin{align*}
    \tilde{\rho}_d
    &= \frac{\cov(Y^{\perp W\mid D=d}, \lambda_1(P)^{\perp W\mid D=d}\mid D=d)}{\var(\lambda_d(P)^{\perp W\mid D=d}\mid D=d)} \\
    &= \frac{\cov((\rho_d \lambda_d(P) + W'\eta_d \lambda_d(P))^{\perp W\mid D=d}, \lambda_d(P)^{\perp W\mid D=d}\mid D=d)}{\var(\lambda_d(P)^{\perp W\mid D=d}\mid D=d)} \\
    &= \rho_d + \frac{\cov((W'\lambda_d(P))^{\perp W\mid D=d}, \lambda_d(P)^{\perp W\mid D=d} \mid D=d)}{\var(\lambda_d(P)^{\perp W\mid D=d}\mid D=d)} ~~\eta_d \\
    &= \rho_d + 
    \frac{\cov(W'\lambda_d(P), \lambda_d(P)^{\perp W\mid D=d} \mid D=d)}{\var(\lambda_d(P)^{\perp W\mid D=d}\mid D=d)} ~~\eta_d 
\end{align*}
The second line holds by noting that correct regression equation \eqref{eq:longreg} gives
\[
    Y = \mu_d + W'\tau_d + \rho_d \lambda_d(P) + W'\eta_d \lambda_d(P) + \epsilon_d \quad \text{conditional on } D = d.
\]
where $\epsilon_d \equiv Y - \Exp[Y\mid D=d, W, P]$. This implies 
\[
    Y^{\perp W\mid D=d} = \left(\rho_d \lambda_d(P) + W'\eta_d \lambda_d(P)\right)^{\perp W\mid D=d}
\]
since $\epsilon_d$ is uncorrelated with $W$ conditional on $D=d$. So we  establish the bias formula for $\tilde{\rho}_d - \rho_d$.

Alternatively, we can also apply the FWL theorem to partial out the linear effects of $\lambda_d(W)$ in the misspecified regression, giving 
\begin{align*}
    &Y^{\perp \lambda_1(P)\mid D=1} = \tilde{\tau}_1'W^{\perp \lambda_1(P)\mid D=1} + Y^{\perp W, \lambda_1(P)\mid D=1}  &\text{conditional on } D = 1\\
    &Y^{\perp \lambda_0(P)\mid D=0} = \tilde{\tau}_0'W^{\perp \lambda_0(P)\mid D=0} + Y^{\perp W, \lambda_0(P)\mid D=0} &\text{conditional on } D = 0
\end{align*}
In this way, $\tilde{\tau}_d$ is the OLS coefficient on $W$ in a regression of $Y^{\perp \lambda_d(P)\mid D=d}$ on $W^{\perp \lambda_d(P)\mid D=d}$: 
\[
    \tilde{\tau}_d = \Exp[(W^{\perp \lambda_d(P)\mid D=d})(W^{\perp \lambda_d(P)\mid D=d})'\mid D=d]^{-1}\Exp[(W^{\perp \lambda_d(P)\mid D=d})(Y^{\perp \lambda_d(P)\mid D=d})\mid D=d].
\]
The correct regression \eqref{eq:longreg} implies that  
$Y^{\perp \lambda_d(P)\mid D=d} = (W'\tau_d + W'\eta_d\lambda_d(P))^{\perp \lambda_d(P)\mid D=d}$. Plugging it into the OLS estimand $\tilde{\tau}_d$ then gives
\begin{align*}
    \tilde{\tau}_d - \tau_d 
    &= \Exp[(W^{\perp \lambda_d(P)\mid D=d})(W^{\perp \lambda_d(P)\mid D=d})'\mid D=d]^{-1}\Exp[(W^{\perp \lambda_1(P)\mid D=d})(W'\lambda_d(P))^{\perp \lambda_d(P)\mid D=d}\mid D=d]~\eta_d \\
    &= \Exp[(W^{\perp \lambda_d(P)\mid D=d})(W^{\perp \lambda_d(P)\mid D=d})'\mid D=d]^{-1}\Exp[(W^{\perp \lambda_1(P)\mid D=d})(W'\lambda_d(P))\mid D=d]~\eta_d 
\end{align*}
which establishes the bias formula for $\tilde{\tau}_d - \tau_d$.
\end{proof}



\begin{proof}[Proof of Theorem \ref{thm:bias_formula_specific}]
We begin by noting that $\cov(W, \lambda_d(P)\mid D=d) = 0_{L\times 1}$ implies 
\begin{equation}
\label{eq:reg_resid_1}
    W^{\perp \lambda_d(P)\mid D=d} = W - \Exp[W\mid D=d] \quad \text{and} \quad \lambda_d(P)^{\perp W\mid D=d} = \lambda_d(P) - \Exp[\lambda_d(P)\mid D=d].
\end{equation}














First, we simplify the bias formula in Lemma \ref{lem:bias_formula_general}, which would lead us to compute the bias on causal parameter of interests. The general bias formula on $\tau_d$ can be simplified by the following derivations:
\begin{align}
    \tilde{\tau}_d
    &= \tau_d + \Exp[(W^{\perp \lambda_d(P)\mid D=d})(W^{\perp \lambda_d(P)\mid D=d})'\mid D=d]^{-1}\Exp[(W^{\perp \lambda_d(P)\mid D=d})(W'\lambda_d(P))\mid D=d]~\eta_d  \notag \\
    &= \tau_d + \var(W\mid D=d)^{-1}\Exp[(W-\Exp[W\mid D=d])W'\lambda_d(P)\mid D=d] ~\eta_d \notag \\
    &= \tau_d + \var(W\mid D=d)^{-1}\left(\Exp[WW'\lambda_d(P)\mid D=d] - \Exp[W\mid D=d]\Exp[W'\lambda_d(P)\mid D=d]\right) \eta_d \notag \\
    &= \tau_d + \var(W\mid D=d)^{-1}\var(W\mid D=d) \Exp[\lambda_d(P)\mid D=d] ~\eta_d \notag \\
    &= \tau_d + \Exp[\lambda_d(P)\mid D=d] \eta_d. \label{eq:bias_tau}
\end{align}
The first equality is given by the Lemma \ref{lem:bias_formula_general}. The second equality holds by \eqref{eq:reg_resid_1}. The fourth equality holds by assumption $\cov(WW',\lambda_d(P)\mid D=d) = 0_{L\times L}$ and $\cov(W,\lambda_d(P)\mid D=d) = 0_{L\times 1}$. 

On the other hand, the general bias formula on $\rho_d$ can be simplified by the following derivations:
\begin{align}
    \tilde{\rho}_d
    &= \rho_d + \frac{\cov(W'\lambda_d(P), \lambda_d(P)^{\perp W\mid D=d} \mid D=d)}{\var(\lambda_d(P)^{\perp W\mid D=d}\mid D=d)} ~~\eta_d \notag \\
    &= \rho_d + \frac{\cov(W'\lambda_d(P), \lambda_d(P) - \Exp[\lambda_d(P)\mid D=d]\mid D=d)}{\var(\lambda_d(P)\mid D=d)}~~\eta_d \notag \\
    &= \rho_d + \frac{\Exp[W'\lambda_1(P)^2\mid D=d] - \Exp[W'\mid D=d]\Exp[\lambda_d(P)\mid D=d]^2}{\var(\lambda_d(P)\mid D=d)}~~\eta_d \notag \\
    &= \rho_d + \Exp[W'\eta_d\mid D=d]. \label{eq:bias_rho}
\end{align}
The first equality is given by the Lemma \ref{lem:bias_formula_general}. The second equality holds by \eqref{eq:reg_resid_1}. The third equality holds by assumption that $\cov(W, \lambda_d(P)\mid D=d) = 0_{L\times 1}$. The final equality holds by the assumption that $\cov(W, \lambda_d(P)^2) = 0_{L\times 1}$.

Having simplified the bias formulae in Lemma \ref{lem:bias_formula_general}, now we can derive the bias formula for $\mu_d$ as follows:
\begin{align}
    \tilde{\mu}_d
    &= \Exp[Y - W'\tilde{\tau}_d - \tilde{\rho}_d\lambda_d(P)\mid D=d] \notag \\
    &= \Exp[\mu_d + W'\tau_d + \rho_d\lambda_d(P) + [W\lambda_d(P)]'\eta_d - W'\tilde{\tau}_d - \tilde{\rho}_d\lambda_d(P)\mid D=d] \notag \\
    &=\Exp[\mu_d + [W\lambda_d(P)]'\eta_d - W'\eta_d \Exp[\lambda_d(P)\mid D=d] - \Exp[W'\eta_d\mid D=d]\lambda_d(P)\mid D=d] \notag \\
    &= \mu_d - \Exp[W'\eta_d\mid D=d]\Exp[\lambda_d(P)\mid D=d] \label{eq:bias_mu}
\end{align}
The first equality follows by misspecified regression \eqref{eq:shortreg}. The second equality follows by the correctly specified model \eqref{eq:longreg}. The third equality follows from the bias formula in \eqref{eq:bias_tau} and \eqref{eq:bias_rho}. The last equality holds by the assumption $\cov(W,\lambda_d(P)\mid D=d) = 0_{L\times 1}$.

Given the bias formula in \eqref{eq:bias_tau}, \eqref{eq:bias_rho}, and  \eqref{eq:bias_mu}, now we compute the bias on estimating the slope of MTE curve:
\begin{align*}
    \widetilde{\text{Slope}} - \text{Slope}
    &= [\tilde{\rho}_1 - \tilde{\rho}_0] - \Exp[\rho_1(W) -\rho_0(W)]\\
    &= \Exp[W\mid D=1]'\eta_1 - \Exp[W\mid D=0]'\eta_0 - \Exp[W]'(\eta_1 - \eta_0) \\
    &= \left(\Exp[W\mid D=1] - \Exp[W\mid D=0]\right)'(\Prob(D=0) ~ \eta_1 + \Prob(D=1) ~ \eta_0).
\end{align*}
The second line holds by \eqref{eq:bias_rho}. This establishes the bias formula for the slope of MTE curve.

Next note that \eqref{eq:bias_tau} and \eqref{eq:bias_mu} imply
\begin{align*}
    \widetilde{\text{CATE}} - \text{CATE}
    &= [\tilde{\mu}_1 - \tilde{\mu}_0] + w'(\tilde{\tau}_1 - \tilde{\tau}_0) - [\mu_1 - \mu_0] - w'(\tau_1 - \tau_0) \\
    &= (w - \Exp[W\mid D=1])'\eta_1\times \Exp[\lambda_1(P)\mid D=1] \\
    & \quad - (w - \Exp[W\mid D=0])'\eta_0 \times \Exp[\lambda_0(P)\mid D=0].
\end{align*}
and 
\begin{align*}
    \widetilde{\text{ATE}} - \text{ATE}
    &= [\tilde{\mu}_1 - \tilde{\mu}_0] + \Exp[W]'(\tilde{\tau}_1 - \tilde{\tau}_0) - [\mu_1 - \mu_0] - \Exp[W]'(\tau_1 - \tau_0) \\
    &= (\Exp[W] - \Exp[W\mid D=1])'\eta_1\times \Exp[\lambda_1(P)\mid D=1] \\
    & \quad - (\Exp[W] - \Exp[W\mid D=0])'\eta_0 \times \Exp[\lambda_0(P)\mid D=0].
\end{align*}

So we have established the bias formula for ATE, CATE, and slope of MTE curve under Assumption \ref{asp:weak_exogeneous_covariates}.1. From this, note that the bias on ATE and slope would vanish if we additionally impose Assumption \ref{asp:weak_exogeneous_covariates}.2, i.e., $\Exp[W] = \Exp[W\mid D=1] = \Exp[W\mid D=0]$, so the proof is complete.
\end{proof}

\label{sec:main_lemmas}

In this section, I provide the statement of supporting lemmas used in  Appendix \ref{sec:main_proofs}. The proofs of these lemmas can be found in Online Appendix \ref{appendix:lemma_proofs}.


\begin{lemma}
\label{lem:convergence_p_beta}
	For a sequence of distributions $\{(\theta_{F_n}, F_n)\}_{n=1}^\infty \subset \mathcal{P}$, suppose 
	\begin{enumerate}
		\item $q_{F_n}(z_\ell) \to q_{\infty}(z_\ell)$ for each $\ell = 0,1,\ldots,K$,
		\item $p_{F_n} \to p_\infty$,
		\item $\beta_{F_n} = (\beta_{F_n,1}', \beta_{F_n,0}')' \to \beta_{\infty}$,
		\item $\sigma^2_{F_n,d\ell} \to \sigma_{\infty,d\ell}^2$ for $d = 0,1$ and $\ell = 0,1,\ldots,K$.
	\end{enumerate}
	Then we have 
	\begin{enumerate}
	\item[(a)] The following convergence holds
	\begin{equation}
	\label{eq:clt_p_beta}
            \begin{pmatrix}
            \hat{Z}_p \\
            \hat{Z}_{\beta_1} \\
            \hat{Z}_{\beta_0} \\
            \hat{Z}_{q}
            \end{pmatrix}
            ~~\equiv~~
		\sqrt{n}
		\begin{pmatrix}
			\hat{p} - p_{F_n} \\
			\hat{\beta}_1 - \beta_{F_n, 1} \\
			\hat{\beta}_0 - \beta_{F_n, 0} \\
			\hat{q} - q_{F_n}
		\end{pmatrix}
		~~\xrightarrow{d}~~
		\begin{bmatrix}
			\mathcal{Z}_p \\
			\mathcal{Z}_{\beta_1} \\
			\mathcal{Z}_{\beta_0} \\
			\mathcal{Z}_q
		\end{bmatrix},
	\end{equation}
	where 
	\begin{align*}
            (\mathcal{Z}_p', \mathcal{Z}_{\beta_1}', \mathcal{Z}_{\beta_0}', \mathcal{Z}_q')' 
            ~~&\sim~~
		\normal\left(0_{3(K+1)\times 1},  \quad 
		\diag\{\Sigma_{p,\infty}, \Sigma_{\beta_1,\infty}, \Sigma_{\beta_0,\infty},\Sigma_{q,\infty}\}\right), \\
		\Sigma_{p,\infty} 
            &\equiv \diag\left\{\frac{p_\infty(z_\ell) (1-p_\infty(z_\ell))}{q_\infty(z_\ell)}: \ell = 0,1,\ldots,K\right\} \\
		\Sigma_{\beta_{1},\infty} 
            &\equiv
			\diag\left\{\frac{\sigma_{\infty,1\ell}^2}{q_\infty(z_\ell)p_\infty(z_\ell)}:\ell = 0,1,\ldots,K\right\} \\
		\Sigma_{\beta_0, \infty} 
            &\equiv 
			\diag\left\{\frac{\sigma_{\infty,0\ell}^2}{q_\infty(z_\ell)(1-p_\infty(z_\ell))}: \ell = 0,1,\ldots,K\right\} \\
		\Sigma_{q,\infty} 
            &\equiv \{\Sigma_{q,\infty}[i,j]\}_{i,j = 0,1,\ldots,K},
	\end{align*}
        with
        \[
            \Sigma_{q,\infty}[i,j] = 
            \begin{cases}
            p_\infty(z_i) (1-p_\infty(z_i)) \\
            -p_\infty(z_i)p_\infty(z_j).
            \end{cases}
        \]
	\item[(b)] We have consistent estimators for the asymptotic variance:
	\begin{align*}
		&\hat{\Sigma}_{p}  ~~\xrightarrow{p}~~ \Sigma_{p,\infty} \\
		&\hat{\Sigma}_\beta ~~\xrightarrow{p}~~ \Sigma_{\beta,\infty} \equiv \diag\{\Sigma_{\beta_1,\infty}, \Sigma_{\beta_0, \infty}\} \\
		&\hat{\Sigma}_q ~~\xrightarrow{p}~~ \Sigma_{q,\infty}.
	\end{align*}
        \item[(c)] The convergence results in part (a) and (b) also hold for any subsequence $\{p_n\}$ provided that the conditions given in the lemma hold along $\{p_n\}$.
	\end{enumerate}
\end{lemma}



\begin{lemma}
\label{lem:pd_variance}
Suppose $c_\mu \neq 0$ or $c_\rho \neq 0$ are fixed weights and let $\lambda = c'\theta$. For any $(\theta,F)\in\mathcal{P}$, the asymptotic variance matrix 
\[
    S \equiv [\partial_p g(\lambda)]\Sigma_p[\partial_{p'} g(\lambda)] + [\partial_{\beta_1} g(\lambda)]\Sigma_{\beta_1}[\partial_{\beta_1'} g(\lambda)] + [\partial_{\beta_0} g(\lambda)]\Sigma_{\beta_0}[\partial_{\beta_0'} g(\lambda)]
\]
is uniformly bounded and positive definite. That is, 
\begin{equation}
\label{eq:bdd_above_zero}
    \inf_{(\theta,F)\in \mathcal{P}} \lambda_{\min}(S) > 0,
\end{equation}
and 
\begin{equation}
\label{eq:bdd_below_inf}
    \sup_{(\theta,F)\in \mathcal{P}} \lambda_{\max}(S) < \infty,
\end{equation}
where $\lambda_{\min}(S)$ and $\lambda_{\max}(S)$ denote the smallest and largest eigenvalues (or singular value) of $S$, respectively.
\end{lemma}
\begin{remark}
This lemma shows that any choice of nonzero linear weights $c_\mu$ and $c_\rho$ would not entail an asymptotic singular covariance matrix for AR test, which is essential for establishing uniform validity.
\end{remark}
\begin{remark}
Indeed, we can relax the restriction that $\lambda = c'\theta$ and show this result for all $\lambda$ that belongs to a compact subset on the real line, which will be useful to establish the power property of the test. Since the above statement is sufficient to prove the uniform validity of the conditional Wald test, I do not pursue this extension here.
\end{remark}

\begin{lemma}
\label{lem:NS_cond}
    Suppose the conditions in Proposition \ref{prop:subsequence_AR_validity} hold for a sequence $(\lambda_n, F_n)$ for which $\sqrt{n}\|\pi_{F_{n}}\| \to s_\infty < \infty$. Then $\Upsilon_\infty = (\mathcal{Z}_h, S_\infty, \Sigma_{p,\infty}, \partial_p g(\lambda_\infty))$ belongs to $\mathcal{U}$ defined in \eqref{eq:defn_set_C} almost surely. That is, 
    \[
        \Prob_{\eta^*}\left(\mathcal{Z}_h + [\partial_p \pi] \Sigma_{p,\infty} \partial_{p'} g(\lambda_\infty) S_\infty^{-1/2}\eta^* \neq 0_{K\times 1} \mid \mathcal{Z}_h \right) = 1 \quad \text{a.s.}
    \]
\end{lemma}






\begin{lemma}
\label{lem:cond_stat}[\citet[Lemma 10.3]{andrews/guggenberger:2017}]
Assume the following conditions hold under a sequence of DGPs $\{(\theta_{F_n}, F_n)\}_{n\geq 1}$:
\begin{enumerate}
\item The scaled singular values converge
\[
	\sqrt{n}\tau_{j,F_n} \to 
	\begin{cases}
		\infty & \text{if } j \leq q \\
		t_j \in [0,\infty) & \text{if } j > q
	\end{cases}
\]
\item $C_{F_n}$ and $B_{F_n}$ converge to their limits $C_{\infty}$ and $B_{\infty}$, respectively.
\item The moment condition and the normalized $\hat{D}(\theta_{F_n})$ converge jointly:
\begin{align*}
	\sqrt{n}
	\begin{pmatrix}
		\hat{A}\theta_{F_n} - \hat{\beta} \\
		\operatorname*{vec}(\hat{D}(\theta_{F_n})) - \operatorname*{vec}(A_{F_n})
	\end{pmatrix}
	~~\xrightarrow{d}~~
	\begin{pmatrix}
		\mathcal{Z}_{\mathfrak{m}} \\
		\operatorname{vec}(\mathcal{Z}_D)
	\end{pmatrix}
\end{align*}
where $\mathcal{Z}_D = (\mathcal{Z}_{d_1}, \ldots, \mathcal{Z}_{d_{2(M+1)}})$ is independent of $\mathcal{Z}_{\mathfrak{m}}$.
\end{enumerate}
Then we have
\[
	n^{1/2}\hat{D}(\theta_{F_n}) B_{F_n} \Psi_{F_n} ~~\xrightarrow{d}~~ \mathcal{D} = O_p(1)
\]
where
\[
	\Psi_{F_n} \equiv \diag\{(\sqrt{n}\tau_{1,F_n})^{-1},\ldots, (\sqrt{n}\tau_{q,F_n})^{-1}, 1,\ldots, 1\} \in \R^{2(M+1)\times 2(M+1)}.
\]
Moreover, $\mathcal{D}$ is independent of $\mathcal{Z}_{\mathfrak{m}}$.
\end{lemma}



\begin{lemma}
	\label{lem:new_cond_stat}
	Suppose the assumptions in Lemma \ref{lem:cond_stat} hold. Let $\xi\in\R^{2(K+1)\times 2(M+1)}$ be a matrix of i.i.d. standard normal random variables and $\kappa > 0$. Then 
	\[
		n^{1/2} (\hat{D}(\theta_{F_n}) + \kappa n^{-1/2}\xi) B_{F_n} \Psi_{F_n} 
		~~\xrightarrow{d}~~
		\mathcal{D}_\xi	
	\]
	where $\mathcal{D}_\xi$ has full rank with probability one and is independent of $\mathcal{Z}_{\mathfrak{m}}$.
\end{lemma}

\begin{lemma}[The $c_r$ inequality]
\label{lem:cr_ineq}
	Let $X$ and $Y$ be random variables with $\Exp|X|^r < \infty$ and $\Exp|Y|^r < \infty$ for some $r > 0$. Then 
	\[
		\Exp|X+Y|^r \leq c_r\left(\Exp|X|^r + \Exp|Y|^r\right)	
	\]  
	where $c_r = 1$ if $r \leq 1$ and $c_r = 2^{r-1}$ if $r > 1$.
\end{lemma}

\begin{lemma}[WLLN for $L^{1+\delta}$ triangular array]
\label{lem:wlln_array}
Let $\{X_{ni}\}$ be a row-wise i.i.d. triangular array of random variables. Suppose
\begin{equation}
\label{eq:wlln}
	\sup_{n}\Exp |X_{ni}|^{1+\delta} < \infty
\end{equation}
for some $\delta > 0$. 
Then 
\[
	\frac{1}{n}\sum_{i=1}^n X_{ni} - \Exp[X_{ni}] ~~\xrightarrow{p}~~ 0.
\]
\end{lemma}


\begin{lemma}[Multivariate Lyapunov CLT]
\label{lem:clt_array}
	Let $\{X_{ni}\}$ be a row-wise i.i.d. triangular array of random vectors in $\R^k$ with expectations $\Exp[X_{ni}] = 0$ and covariance matrices $\Sigma_{n} = \Exp[X_{ni}X_{ni}']$.  Suppose 
\begin{equation}
\label{eq:lyapunov_var}
	\Sigma_n \to \Sigma \geq 0
\end{equation}
and for some $\delta > 0$
\begin{equation}
\label{eq:lyapunov_moment}
	\sup_{n} \Exp\|X_{ni}\|^{2+\delta} < \infty.
\end{equation}
Then as $n\to \infty$,
\[
	\frac{1}{\sqrt{n}}\sum_{i=1}^n X_i ~~\xrightarrow{d}~~ \normal(0,\Sigma).
\]
\end{lemma}

